fn normalize(s: &str) -> String {
  let mut t = s.to_lowercase().trim().to_string();
  t = t.replace("ё", "е");
  t = t.chars().filter(|c| !matches!(c, '!' | '?' | '.' | ',' )).collect();
  t.split_whitespace().collect::<Vec<_>>().join(" ")
}

